reactions.onInit:
api.ensureLinkedBonus({
    items: [item],
    bonusData: {
        id: `siege_armor_${item.id}`,
        name: "Siege Armor",
        type: "immunity",
        subtype: "resistance",
        damageTypes: ["all"],
        condition: (state, actor, data, context) => {
            const api = game.modules.get("lancer-automations")?.api;
            const attacker = actor.getActiveTokens()[0];
            const defender = canvas.tokens.get(context.ownerTokenId);
            return api.getTokenDistance(attacker, defender) > 3;
        }
    },
    addOptions: { 
        duration: "constant" 
    }
});

reactions.activationCode:
const extraT = triggerData.targets.length - 1;
const dmg = api.tierValue(reactorToken, [2, 3, 4]);
const totalDmg = extraT * dmg;

// bombard only has explosive weapons, but just in case
const dmgType = triggerData.flowState.data.damage?.[0]?.type || "Explosive";
triggerData.flowState.data.damage.push({ 
    type: dmgType, 
    val: String(totalDmg) 
});

const dmg = api.tierValue(reactorToken, [4, 6, 8]);

for (const target of triggerData.hitTokens) {
    await api.addGlobalBonus(target.actor, {
        name: "Expose Weakness", 
        type: "damage",
        damage: [{ type: "Variable", val: String(dmg) }],
        applyToTargetter: true,
        uses: 1,
        consumeOnUsage: true,
    }, {
        duration: "indefinite",
        origin: reactorToken,
        consumption: {
            trigger: "onDamage",
        }
    });
}

reactions.onInit:
api.ensureLinkedBonus({
    items: [item],
    bonusData: {
        id: `stampede_defense_${item.id}`,
        name: "Stampede Defense",
        type: "immunity",
        subtype: "resistance",
        damageTypes: ["all"], 
        condition: (state, actor) => {
            const api = game.modules.get("lancer-automations")?.api;
            const owner = canvas.tokens.get(context.ownerTokenId);
            const statList = ['impaired', 'stunned', 'immobilized', 'shredded', 'slow', 'exposed'];
            return !statList.some(s => owner.actor?.statuses?.has(s));
        }
    },
    addOptions: {
        duration: 'constant'
    }
});

reactions.activationCode:
if (await api.consumeOncePerRound(reactorToken, 'aggression')) {
    const adj = api.getTokensInRange(reactorToken);
    if (!adj || !adj.length) return;

    // do the roll publicly for transparency
    const roll = await new Roll(`1d${adj.length}`).evaluate();
    await triggerData.startRelatedFlow(); // dump trait card on chat
    await roll.toMessage({
        speaker: ChatMessage.getSpeaker({ token: reactorToken.document }),
        flavor: "Choosing random character adjacent to the Berserker"
    });

    const target = adj[roll.total - 1];
    const chainAxe = api.findItemByLid(reactorToken, 'npcf_chain_axe_berserker');
    await api.attackWith(chainAxe, [target]);
};

if (await api.consumeOncePerRound(reactorToken, 'blip')) {
    const targets = await api.chooseToken(reactorToken, {
        title: "BLIP // SELECT ALLY",
        description: "Choose an allied character within Sensors to teleport.",
        range: 'sensors',
        disposition: 'friendly',
        includeSelf: false
    });

    if (!targets || !targets.length) return;
    const ally = targets[0];

    await api.moveToken(ally, {
        teleport: true,
        range: 5,
        title: "BLIP // TELEPORT",
        description: `Teleport ${ally.name} 5 spaces in any direction.`
    });
};

